def countLongKnightWalks(m, n, k):
    MOD = 10 ** 9 + 7
    s = m * n
    A = [[0] * s for _ in range(s)]
    for r in range(m):
        for c in range(n):
            for dr, dc in ((1, 2), (2, 1), (-1, 2), (-2, 1), (1, -2), (2, -1), (-1, -2), (-2, -1)):
                a, b = r + dr, c + dc
                if 0 <= a < m and 0 <= b < n:
                    A[r * n + c][a * n + b] = 1
    v = [1] * s
    P = A
    while k:
        if k & 1:
            v = [sum(x * y for x, y in zip(row, v)) % MOD for row in P]
        k >>= 1
        if k:
            cols = list(zip(*P))
            P = [[sum(x * y for x, y in zip(row, col)) % MOD for col in cols] for row in P]
    return sum(v) % MOD
